@page "/apply"
@rendermode InteractiveServer
@using sv_a8a526490cbf4770bcaa7735edd01b26.Models
@using sv_a8a526490cbf4770bcaa7735edd01b26.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* Step Indicator Bar *@
<div class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
            <div class="step-circle">
                @if (IsStepCompleted(stepIndex))
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (stepIndex < StepNames.Length - 1)
        {
            <div class="step-connector @(IsStepCompleted(stepIndex) ? "completed" : "")"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(_errorMessage))
{
    <div class="alert alert-danger mt-3">@_errorMessage</div>
}

@* Step Content *@
<div class="step-content mt-4">
    @switch (_currentStep)
    {
        case 0:
            @RenderPersonalInfo();
            break;
        case 1:
            @RenderWorkHistory();
            break;
        case 2:
            @RenderReferences();
            break;
        case 3:
            @RenderCoverLetter();
            break;
        case 4:
            @RenderReviewSubmit();
            break;
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int _currentStep = 0;
    private string _errorMessage = string.Empty;
    private bool _isProcessing = false;
    private bool _isSubmitted = false;
    private int? _applicationId;

    // Step 1 - Personal Info
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2 - Work History
    private List<WorkEntryForm> _workEntries = new() { new WorkEntryForm() };

    // Step 3 - References
    private List<ReferenceForm> _references = new() { new ReferenceForm(), new ReferenceForm() };

    // Step 4 - Cover Letter
    private string _coverLetter = string.Empty;
    private const int MaxCoverLetterChars = 2000;

    private string GetStepClass(int step)
    {
        if (step == _currentStep) return "active";
        if (IsStepCompleted(step)) return "completed";
        return "dimmed";
    }

    private bool IsStepCompleted(int step) => step < _currentStep;

    private void NavigateToStep(int step)
    {
        if (IsStepCompleted(step) && !_isSubmitted)
        {
            _currentStep = step;
            _errorMessage = string.Empty;
        }
    }

    private async Task NextStep()
    {
        _errorMessage = string.Empty;
        _isProcessing = true;

        try
        {
            if (!ValidateCurrentStep())
                return;

            if (_currentStep == 0)
            {
                var emailValid = await ApplicationService.ValidateEmailAsync(_email);
                if (!emailValid)
                {
                    _errorMessage = "Please enter a valid email address.";
                    return;
                }
            }

            _currentStep++;
        }
        finally
        {
            _isProcessing = false;
        }
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
        {
            _currentStep--;
            _errorMessage = string.Empty;
        }
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(_fullName))
                { _errorMessage = "Full name is required."; return false; }
                if (string.IsNullOrWhiteSpace(_email))
                { _errorMessage = "Email is required."; return false; }
                if (string.IsNullOrWhiteSpace(_phone))
                { _errorMessage = "Phone is required."; return false; }
                if (string.IsNullOrWhiteSpace(_address))
                { _errorMessage = "Address is required."; return false; }
                return true;

            case 1:
                foreach (var entry in _workEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company))
                    { _errorMessage = "Company name is required for all entries."; return false; }
                    if (string.IsNullOrWhiteSpace(entry.Title))
                    { _errorMessage = "Job title is required for all entries."; return false; }
                    if (entry.StartDate == default)
                    { _errorMessage = "Start date is required for all entries."; return false; }
                }
                return true;

            case 2:
                foreach (var r in _references)
                {
                    if (string.IsNullOrWhiteSpace(r.Name))
                    { _errorMessage = "Name is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Relationship))
                    { _errorMessage = "Relationship is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Email))
                    { _errorMessage = "Email is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Phone))
                    { _errorMessage = "Phone is required for all references."; return false; }
                }
                return true;

            case 3:
                if (string.IsNullOrWhiteSpace(_coverLetter))
                { _errorMessage = "Cover letter is required."; return false; }
                if (_coverLetter.Length > MaxCoverLetterChars)
                { _errorMessage = $"Cover letter must be {MaxCoverLetterChars} characters or fewer."; return false; }
                return true;

            default:
                return true;
        }
    }

    private async Task SubmitApplication()
    {
        _errorMessage = string.Empty;
        _isProcessing = true;

        try
        {
            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
            var workHistory = new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? string.Empty)
            ).ToList());
            var references = _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)
            ).ToList();

            var application = new JobApplication(personal, workHistory, references, _coverLetter);
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _isSubmitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isProcessing = false;
        }
    }

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryForm());

    private void RemoveWorkEntry(WorkEntryForm entry)
    {
        if (_workEntries.Count > 1)
            _workEntries.Remove(entry);
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceForm());
    }

    private void RemoveReference(ReferenceForm reference)
    {
        if (_references.Count > 2)
            _references.Remove(reference);
    }

    private void EditSection(int step)
    {
        _currentStep = step;
        _errorMessage = string.Empty;
    }

    // Form helper classes
    private class WorkEntryForm
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string? Description { get; set; } = string.Empty;
    }

    private class ReferenceForm
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }

    // Render fragments
    private RenderFragment RenderPersonalInfo() => __builder =>
    {
        <h3>Personal Information</h3>
        <div class="mb-3">
            <label class="form-label">Full Name *</label>
            <input type="text" class="form-control" @bind="_fullName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email *</label>
            <input type="email" class="form-control" @bind="_email" />
        </div>
        <div class="mb-3">
            <label class="form-label">Phone *</label>
            <input type="tel" class="form-control" @bind="_phone" />
        </div>
        <div class="mb-3">
            <label class="form-label">Address *</label>
            <input type="text" class="form-control" @bind="_address" />
        </div>
        <div class="d-flex justify-content-end">
            <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">
                @if (_isProcessing) { <span>Validating...</span> } else { <span>Next</span> }
            </button>
        </div>
    };

    private RenderFragment RenderWorkHistory() => __builder =>
    {
        <h3>Work History</h3>
        @for (int i = 0; i < _workEntries.Count; i++)
        {
            var entry = _workEntries[i];
            var entryIndex = i;
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5>Position @(entryIndex + 1)</h5>
                    @if (_workEntries.Count > 1)
                    {
                        <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(entry)">Remove</button>
                    }
                </div>
                <div class="mb-3">
                    <label class="form-label">Company Name *</label>
                    <input type="text" class="form-control" @bind="entry.Company" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Job Title *</label>
                    <input type="text" class="form-control" @bind="entry.Title" />
                </div>
                <div class="row mb-3">
                    <div class="col-md-6">
                        <label class="form-label">Start Date *</label>
                        <input type="date" class="form-control" @bind="entry.StartDate" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">End Date</label>
                        <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                        <div class="form-check mt-1">
                            <input type="checkbox" class="form-check-input" @bind="entry.IsCurrent" id="@($"current-{entryIndex}")" />
                            <label class="form-check-label" for="@($"current-{entryIndex}")">Currently working here</label>
                        </div>
                    </div>
                </div>
                <div class="mb-3">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" rows="3" @bind="entry.Description"></textarea>
                </div>
            </div>
        }
        <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">Next</button>
        </div>
    };

    private RenderFragment RenderReferences() => __builder =>
    {
        <h3>References</h3>
        @for (int i = 0; i < _references.Count; i++)
        {
            var reference = _references[i];
            var refIndex = i;
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5>Reference @(refIndex + 1)</h5>
                    @if (_references.Count > 2)
                    {
                        <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(reference)">Remove</button>
                    }
                </div>
                <div class="mb-3">
                    <label class="form-label">Name *</label>
                    <input type="text" class="form-control" @bind="reference.Name" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Relationship *</label>
                    <input type="text" class="form-control" @bind="reference.Relationship" />
                </div>
                <div class="row mb-3">
                    <div class="col-md-6">
                        <label class="form-label">Email *</label>
                        <input type="email" class="form-control" @bind="reference.Email" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Phone *</label>
                        <input type="tel" class="form-control" @bind="reference.Phone" />
                    </div>
                </div>
            </div>
        }
        @if (_references.Count < 3)
        {
            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
        }
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">Next</button>
        </div>
    };

    private RenderFragment RenderCoverLetter() => __builder =>
    {
        <h3>Cover Letter</h3>
        <div class="mb-3">
            <textarea class="form-control" rows="10" @bind="_coverLetter" maxlength="@MaxCoverLetterChars"></textarea>
            <div class="form-text text-end">@(_coverLetter?.Length ?? 0) / @MaxCoverLetterChars characters</div>
        </div>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">Next</button>
        </div>
    };

    private RenderFragment RenderReviewSubmit() => __builder =>
    {
        @if (_isSubmitted)
        {
            <div class="alert alert-success">
                <h4>Application Submitted Successfully!</h4>
                <p>Your application ID is: <strong>@_applicationId</strong></p>
                <p>Thank you for applying. We will review your application and get back to you soon.</p>
            </div>
        }
        else
        {
            <h3>Review & Submit</h3>

            @* Personal Info Section *@
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Personal Information</h5>
                    <button class="btn btn-link btn-sm" @onclick="() => EditSection(0)">Edit</button>
                </div>
                <dl class="row mb-0">
                    <dt class="col-sm-3">Full Name</dt>
                    <dd class="col-sm-9">@_fullName</dd>
                    <dt class="col-sm-3">Email</dt>
                    <dd class="col-sm-9">@_email</dd>
                    <dt class="col-sm-3">Phone</dt>
                    <dd class="col-sm-9">@_phone</dd>
                    <dt class="col-sm-3">Address</dt>
                    <dd class="col-sm-9">@_address</dd>
                </dl>
            </div>

            @* Work History Section *@
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Work History</h5>
                    <button class="btn btn-link btn-sm" @onclick="() => EditSection(1)">Edit</button>
                </div>
                @foreach (var entry in _workEntries)
                {
                    <div class="border-bottom pb-2 mb-2">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                        <small>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mt-1 mb-0">@entry.Description</p>
                        }
                    </div>
                }
            </div>

            @* References Section *@
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>References</h5>
                    <button class="btn btn-link btn-sm" @onclick="() => EditSection(2)">Edit</button>
                </div>
                @foreach (var r in _references)
                {
                    <div class="border-bottom pb-2 mb-2">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        <small>@r.Email | @r.Phone</small>
                    </div>
                }
            </div>

            @* Cover Letter Section *@
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Cover Letter</h5>
                    <button class="btn btn-link btn-sm" @onclick="() => EditSection(3)">Edit</button>
                </div>
                <p style="white-space: pre-wrap;">@_coverLetter</p>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isProcessing">
                    @if (_isProcessing) { <span>Submitting...</span> } else { <span>Submit Application</span> }
                </button>
            </div>
        }
    };
}

