+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">Next</button>
+        </div>
+    };
+
+    private RenderFragment RenderReferences() => __builder =>
+    {
+        <h3>References</h3>
+        @for (int i = 0; i < _references.Count; i++)
+        {
+            var reference = _references[i];
+            var refIndex = i;
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center mb-2">
+                    <h5>Reference @(refIndex + 1)</h5>
+                    @if (_references.Count > 2)
+                    {
+                        <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(reference)">Remove</button>
+                    }
+                </div>
+                <div class="mb-3">
+                    <label class="form-label">Name *</label>
+                    <input type="text" class="form-control" @bind="reference.Name" />
+                </div>
+                <div class="mb-3">
+                    <label class="form-label">Relationship *</label>
+                    <input type="text" class="form-control" @bind="reference.Relationship" />
+                </div>
+                <div class="row mb-3">
+                    <div class="col-md-6">
+                        <label class="form-label">Email *</label>
+                        <input type="email" class="form-control" @bind="reference.Email" />
+                    </div>
+                    <div class="col-md-6">
+                        <label class="form-label">Phone *</label>
+                        <input type="tel" class="form-control" @bind="reference.Phone" />
+                    </div>
+                </div>
+            </div>
+        }
+        @if (_references.Count < 3)
+        {
+            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
+        }
+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">Next</button>
+        </div>
+    };
+
+    private RenderFragment RenderCoverLetter() => __builder =>
+    {
+        <h3>Cover Letter</h3>
+        <div class="mb-3">
+            <textarea class="form-control" rows="10" @bind="_coverLetter" maxlength="@MaxCoverLetterChars"></textarea>
+            <div class="form-text text-end">@(_coverLetter?.Length ?? 0) / @MaxCoverLetterChars characters</div>
+        </div>
+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">Next</button>
+        </div>
+    };
+
+    private RenderFragment RenderReviewSubmit() => __builder =>
+    {
+        @if (_isSubmitted)
+        {
+            <div class="alert alert-success">
+                <h4>Application Submitted Successfully!</h4>
+                <p>Your application ID is: <strong>@_applicationId</strong></p>
+                <p>Thank you for applying. We will review your application and get back to you soon.</p>
+            </div>
+        }
+        else
+        {
+            <h3>Review & Submit</h3>
+
+            @* Personal Info Section *@
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center">
+                    <h5>Personal Information</h5>
+                    <button class="btn btn-link btn-sm" @onclick="() => EditSection(0)">Edit</button>
+                </div>
+                <dl class="row mb-0">
+                    <dt class="col-sm-3">Full Name</dt>
+                    <dd class="col-sm-9">@_fullName</dd>
+                    <dt class="col-sm-3">Email</dt>
+                    <dd class="col-sm-9">@_email</dd>
+                    <dt class="col-sm-3">Phone</dt>
+                    <dd class="col-sm-9">@_phone</dd>
+                    <dt class="col-sm-3">Address</dt>
+                    <dd class="col-sm-9">@_address</dd>
+                </dl>
+            </div>
+
+            @* Work History Section *@
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center">
+                    <h5>Work History</h5>
+                    <button class="btn btn-link btn-sm" @onclick="() => EditSection(1)">Edit</button>
+                </div>
+                @foreach (var entry in _workEntries)
+                {
+                    <div class="border-bottom pb-2 mb-2">
+                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
+                        <small>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</small>
+                        @if (!string.IsNullOrWhiteSpace(entry.Description))
+                        {
+                            <p class="mt-1 mb-0">@entry.Description</p>
+                        }
+                    </div>
+                }
+            </div>
+
+            @* References Section *@
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center">
+                    <h5>References</h5>
+                    <button class="btn btn-link btn-sm" @onclick="() => EditSection(2)">Edit</button>
+                </div>
+                @foreach (var r in _references)
+                {
+                    <div class="border-bottom pb-2 mb-2">
+                        <strong>@r.Name</strong> (@r.Relationship)<br />
+                        <small>@r.Email | @r.Phone</small>
+                    </div>
+                }
+            </div>
+
+            @* Cover Letter Section *@
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center">
+                    <h5>Cover Letter</h5>
+                    <button class="btn btn-link btn-sm" @onclick="() => EditSection(3)">Edit</button>
+                </div>
+                <p style="white-space: pre-wrap;">@_coverLetter</p>
+            </div>
+
+            <div class="d-flex justify-content-between">
+                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isProcessing">
+                    @if (_isProcessing) { <span>Submitting...</span> } else { <span>Submit Application</span> }
+                </button>
+            </div>
+        }
+    };
+}
+

